package fraymus.workspace;
import org.json.*;
import java.nio.charset.StandardCharsets;
import java.io.*;
import java.util.*;
import java.util.zip.GZIPOutputStream;

/** Actual Java projections and numeric-only source evidence. Personal pixels never enter reports. */
final class Alignment041Report {
    static JSONObject overlay(JSONObject snapshot){
        var reg=snapshot.getJSONObject("registration");var fit=reg.getJSONObject("fit");var nativeFrame=WorldFrames.copy(snapshot.getJSONObject("native"));var rows=nativeFrame.getJSONArray("entities");var geometry=reg.getJSONObject("geometry");var corners=geometry.getJSONArray("worldPoints");var centre=new double[3];double span=.2;int at=0;
        for(Object raw:corners){var p=MatRegistration041.map(fit,PlaneCalibration.point((JSONArray)raw));for(int i=0;i<3;i++)centre[i]+=p[i]/corners.length();rows.put(marker("mat041:"+reg.getString("id")+":"+at++,"Declared mat landmark",p,.003,false));for(Object other:corners)span=Math.max(span,MatRegistration041.distance(p,MatRegistration041.map(fit,PlaneCalibration.point((JSONArray)other)))*1.2);}
        String selected="";var t=snapshot.optJSONObject("trial");var point=new JSONObject().put("usable",false).put("heightKnown",false).put("physicalContactKnown",false);
        if(t!=null&&!t.getJSONArray("trace").isEmpty()){var row=t.getJSONArray("trace").getJSONObject(t.getJSONArray("trace").length()-1);boolean usable=snapshot.getBoolean("nativeCurrent")&&fit.getBoolean("passed")&&row.getJSONObject("reference").getBoolean("valid");point.put("usable",usable).put("runId",t.getString("id")).put("ordinal",row.getInt("ordinal")).put("imageSha256",row.getJSONObject("frame").getString("imageSha256")).put("acceptedMeasurement",row.getJSONObject("estimate").getBoolean("accepted")).put("status",row.getJSONObject("estimate").getString("status"));if(usable){var p=MatRegistration041.map(fit,PlaneCalibration.point(row.getJSONObject("estimate").getJSONArray("positionM")));point.put("nativePlanePointM",new JSONArray(p)).put("matPointM",row.getJSONObject("estimate").getJSONArray("positionM")).put("modelRadiusM",row.getJSONObject("estimate").getDouble("radiusM")*fit.getDouble("scale")+fit.getDouble("fitRmsM")+fit.getDouble("maxCheckErrorM"));selected="observation041:"+reg.getString("bodyId");point.put("markerId",selected);rows.put(marker(selected,"Registered surface-coordinate marker; height unknown",p,.010,true));}}
        nativeFrame.put("selectedId",selected).put("focus",new JSONObject().put("center",new JSONArray(centre)).put("span",span)).put("registeredPoint",point).put("nativeSnapshotHash",snapshot.getJSONObject("native").getString("snapshotHash")).put("registrationId",reg.getString("id")).put("limits","Diagnostic registered surface markers; native entities/poses remain exact. Marker size/offset are display choices, not measured object geometry or height.");nativeFrame.remove("snapshotHash");nativeFrame=WorldFrames.copy(nativeFrame);nativeFrame.put("snapshotHash",WorldFrames.hash(nativeFrame));return nativeFrame;
    }
    private static JSONObject marker(String id,String label,double[] p,double size,boolean dynamic){var position=p.clone();position[1]+=.001;return new JSONObject().put("id",id).put("label",label).put("shape","box").put("position",new JSONArray(position)).put("size",new JSONArray(new double[]{size,.002,size})).put("rotation",new JSONArray(new double[]{0,0,0,1})).put("dynamic",dynamic).put("role","diagnostic-observation-marker").put("visualOffsetM",.001);}
    static JSONObject view(JSONObject snapshot,String view){var overlay=overlay(snapshot);return WorldFrames.copy(SpatialProjection040.project(overlay,new JSONObject().put("view",view).put("width",800).put("height",450)).put("registeredPoint",overlay.getJSONObject("registeredPoint")).put("sourceSnapshotHash",snapshot.getString("snapshotHash")));}
    static JSONObject packed(JSONObject snapshot)throws Exception{byte[] raw=exported(snapshot).toString().getBytes(StandardCharsets.UTF_8);var out=new ByteArrayOutputStream();try(var gzip=new GZIPOutputStream(out)){gzip.write(raw);}return new JSONObject().put("format","fraynix.alignment041-gzip-v1").put("rawBytes",raw.length).put("rawSha256",PerceptionStore.hash(raw)).put("gzipBase64",Base64.getEncoder().encodeToString(out.toByteArray()));}
    static JSONObject exported(JSONObject snapshot){return new JSONObject().put("format",Alignment041Store.VERSION).put("snapshot",snapshot).put("scope","Numeric source-qualified evidence, no personal camera pixels; checksum is not native authority");}
    static JSONObject verify(JSONObject in){SpatialScene.keys(in,"format","snapshot","scope");if(!Alignment041Store.VERSION.equals(in.getString("format")))throw new IllegalArgumentException("Unknown alignment format");var s=WorldFrames.copy(in.getJSONObject("snapshot"));String hash=s.getString("snapshotHash");s.remove("snapshotHash");if(!WorldFrames.hash(s).equals(hash))throw new IllegalStateException("Alignment export checksum differs");return new JSONObject().put("passed",true).put("snapshotHash",hash);}
    static String e(String s){return KnowledgeReport.escape(s);}
    static JSONObject build(JSONObject s)throws Exception{
        var reg=s.getJSONObject("registration");var fit=reg.getJSONObject("fit");var trial=s.optJSONObject("trial");var rows=trial==null?new JSONArray():trial.getJSONArray("trace");String status=trial!=null&&trial.has("evaluation")?trial.getJSONObject("evaluation").getString("status")+" / passed="+trial.getJSONObject("evaluation").getBoolean("passed"):"not evaluated";
        var html=new StringBuilder("<p>FRAYNIX / MEASURED ALIGNMENT041</p><h1>Measured plane. Declared native placement.</h1><p id=alignment-hash>").append(s.getString("snapshotHash")).append("</p><p id=alignment-id>").append(reg.getString("id")).append("</p><p id=alignment-trial>").append(trial==null?"none":trial.getString("id")).append("</p><p id=alignment-verdict>").append(status).append("</p><p>Fit RMS ").append(fit.getDouble("fitRmsM")*1000).append("mm; withheld max ").append(fit.getDouble("maxCheckErrorM")*1000).append("mm; independent tape error ").append(fit.getJSONObject("tape").getDouble("absoluteErrorM")*1000).append("mm. Scale ").append(fit.getDouble("scale")).append(". Registration gates passed=").append(fit.getBoolean("passed")).append("; native current=").append(s.getBoolean("nativeCurrent")).append(".</p><p>Fitting corners may be reused from calibration. Withheld landmarks and tape are separate checks. Native placement is declared; object height/contact unknown. Diagnostic marker size/offset is not reconstruction. No native body moved.</p><div class=views>");var files=new JSONObject().put("snapshot-gzip.json",packed(s).toString());
        for(String name:List.of("perspective","top","front","side")){var v=view(s,name);files.put("view-"+name+".json",v.toString());html.append("<section><h2>").append(name).append("</h2><svg viewBox='0 0 800 450'>");for(Object raw:v.getJSONArray("polygons")){var p=(JSONObject)raw;html.append("<polygon points='");for(Object point:p.getJSONArray("points")){var a=(JSONArray)point;html.append(a.getDouble(0)).append(',').append(a.getDouble(1)).append(' ');}html.append("' fill='").append(p.getBoolean("selected")?"#e7b75b":p.getBoolean("dynamic")?"#4a9783":"#304b5c").append("' stroke='#bad9cb'/>");}for(Object raw:v.getJSONArray("centers")){var centre=(JSONObject)raw;if(centre.getString("id").equals(v.getJSONObject("registeredPoint").optString("markerId",""))){var p=centre.getJSONArray("pixel");html.append("<circle cx='").append(p.getDouble(0)).append("' cy='").append(p.getDouble(1)).append("' r='7' fill='none' stroke='#ffe1a3' stroke-width='3'/>");}}html.append("</svg></section>");}html.append("</div><h2>Independent landmark residuals</h2><table><thead><tr><th>Name</th><th>Role</th><th>Error/mm</th></tr></thead><tbody id=alignment-landmarks>");for(Object raw:fit.getJSONArray("landmarks")){var l=(JSONObject)raw;html.append("<tr><td>").append(e(l.getString("name"))).append("</td><td>").append(l.getString("role")).append("</td><td>").append(l.getDouble("errorM")*1000).append("</td></tr>");}html.append("</tbody></table><h2>Actual sampled motion</h2><svg viewBox='0 0 800 260'><text x='18' y='24' fill='#d8eee5'>Mat X / metres over actual source seconds · exact rows in samples.csv</text>");
        var csv=new StringBuilder("ordinal,phase,seconds,measured,referenceValid,predictedX,predictedY,estimateX,estimateY,radiusM\n");double first=rows.isEmpty()?0:rows.getJSONObject(0).getJSONObject("frame").getDouble("seconds"),last=rows.isEmpty()?1:rows.getJSONObject(rows.length()-1).getJSONObject("frame").getDouble("seconds"),lo=0,hi=.3;for(Object raw:rows){var row=(JSONObject)raw;var est=row.getJSONObject("estimate");lo=Math.min(lo,est.getJSONArray("positionM").getDouble(0));hi=Math.max(hi,est.getJSONArray("positionM").getDouble(0));}
        for(Object raw:rows){var row=(JSONObject)raw;var est=row.getJSONObject("estimate");double t=row.getJSONObject("frame").getDouble("seconds"),x=30+740*(t-first)/Math.max(.001,last-first),y=230-180*(est.getJSONArray("positionM").getDouble(0)-lo)/Math.max(.001,hi-lo);html.append("<circle cx='").append(x).append("' cy='").append(y).append("' r='3' fill='").append(est.getBoolean("accepted")?"#8ce0be":"#e7b75b").append("'/>");csv.append(row.getInt("ordinal")).append(',').append(row.getString("phase")).append(',').append(t).append(',').append(est.getBoolean("accepted")).append(',').append(row.getJSONObject("reference").getBoolean("valid")).append(',').append(est.getJSONArray("predictedM").getDouble(0)).append(',').append(est.getJSONArray("predictedM").getDouble(1)).append(',').append(est.getJSONArray("positionM").getDouble(0)).append(',').append(est.getJSONArray("positionM").getDouble(1)).append(',').append(est.getDouble("radiusM")).append('\n');}
        html.append("</svg><p>Green measured estimates; amber predictions. Radius remains an uncalibrated model budget, not probability.</p><pre>").append(e(Alignment041Store.summary(s).toString(2))).append("</pre>");
        files.put("samples.csv",csv.toString()).put("summary.json",Alignment041Store.summary(s).toString(2)).put("index.html","<!doctype html><html lang=en><meta charset=utf-8><meta name=viewport content='width=device-width,initial-scale=1'><title>Measured alignment041</title><style>*{box-sizing:border-box}body{margin:0;padding:24px;background:#10242b;color:#e4f1ed;font:16px/1.65 system-ui;overflow-wrap:anywhere}.views{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}section,pre{background:#19383e;border-radius:12px;padding:14px}svg{width:100%;height:auto;background:#122832}pre{white-space:pre-wrap;max-height:500px;overflow:auto}td,th{text-align:left;padding:8px;border-bottom:1px solid #638b7d}@media(max-width:700px){body{padding:14px}.views{grid-template-columns:1fr}}</style>"+html+"</html>");
        return new JSONObject().put("title","Measured mat alignment041 · "+(trial==null?"registration":trial.getString("kind"))).put("files",files).put("sources",new JSONArray().put(reg.getJSONObject("nativeBinding")).put(reg.getJSONObject("frame")));
    }
}
